#ifndef __MEM_CACHE_PREFETCH_QUEUED_HH__
#define __MEM_CACHE_PREFETCH_QUEUED_HH__

#include <cstdint>
#include <list>
#include <utility>

#include "arch/generic/mmu.hh"
#include "base/statistics.hh"
#include "base/types.hh"
#include "mem/cache/prefetch/base.hh"
#include "mem/packet.hh"

namespace gem5
{

struct QueuedPrefetcherParams;

namespace prefetch
{

class Queued : public Base
{
  protected:
    struct DeferredPacket : public BaseMMU::Translation
    {
        /** Owner of the packet */
        Queued *owner;
        /** Prefetch info corresponding to this packet */
        PrefetchInfo pfInfo;
        /** Time when this prefetch becomes ready */
        Tick tick;
        /** The memory packet generated by this prefetch */
        PacketPtr pkt;
        /** The priority of this prefetch */
        int32_t priority;
        /** Request used when a translation is needed */
        RequestPtr translationRequest;
        ThreadContext *tc;
        bool ongoingTranslation;
        const CacheAccessor *cache;
        // [MDSPEC][R6-P-P04] Shadow queue-valid bit for the P04-a model.
        // gem5's Queued has no explicit valid bit (entries are removed when
        // consumed); this flag lets the injector clear a live entry's valid
        // state WITHOUT dropping it from the list.  Queued::getPacket skips
        // and removes invalid entries at issue time.  Default true => the
        // issue path is byte-identical when no P04 fault is mounted.
        bool chaosQueueValid = true;

        // [MDSPEC][R6-P-P04-a-F5-v2] Physical slot identity: the entry's
        // allocation ordinal modulo the queue capacity.  gem5's ready queue
        // is a std::list without fixed slots; this is the documented logical
        // analogue of a circular FIFO slot.  Default 0 and unused unless the
        // fixed-slot F5 model is latched.
        uint64_t chaosSlot = 0;

        // [MDSPEC][R6-P-P04-c] Observation-only shadows for the
        // entry-selection fault.  They never change the issue path; they let
        // the injector record WHICH entry was swapped into the head and
        // WHICH (correct) head was displaced, and prove at issue time that
        // both were actually issued (one wrong-first, one late) instead of
        // being dropped.  Default false / 0 => byte-identical when no P04-c
        // fault is mounted.
        bool chaosSelectedWrong = false;
        bool chaosDisplacedHead = false;
        uint64_t chaosSelectionFaultId = 0;
        uint64_t chaosSelectionPfid = 0;

        // [MDSPEC][R6-P-P04-b] Observation-only shadows for the tail-pointer
        // -1 fault: the newly inserted entry and the entry it was inserted
        // in front of.  Both remain in the queue and are issued once; the
        // flags only let the injector record the real issue order.
        bool chaosPointerInserted = false;
        bool chaosPointerShifted = false;

        /**
         * Constructor
         * @param o QueuedPrefetcher in charge of this request
         * @param pfi PrefechInfo object associated to this packet
         * @param t Time when this prefetch becomes ready
         * @param p PacketPtr with the memory request of the prefetch
         * @param prio This prefetch priority
         */
        DeferredPacket(Queued *o, PrefetchInfo const &pfi, Tick t,
            int32_t prio, const CacheAccessor &_cache)
            : owner(o), pfInfo(pfi), tick(t), pkt(nullptr),
            priority(prio), translationRequest(), tc(nullptr),
            ongoingTranslation(false), cache(&_cache) {
        }

        bool operator>(const DeferredPacket& that) const
        {
            return priority > that.priority;
        }
        bool operator<(const DeferredPacket& that) const
        {
            return priority < that.priority;
        }
        bool operator<=(const DeferredPacket& that) const
        {
            return !(*this > that);
        }

        /**
         * Create the associated memory packet
         * @param paddr physical address of this packet
         * @param blk_size block size used by the prefetcher
         * @param requestor_id Requestor ID of the access that generated
         * this prefetch
         * @param tag_prefetch flag to indicate if the packet needs to be
         *        tagged
         * @param t time when the prefetch becomes ready
         */
        void createPkt(Addr paddr, unsigned blk_size, RequestorID requestor_id,
                       bool tag_prefetch, Tick t);

        /**
         * Sets the translation request needed to obtain the physical address
         * of this request.
         * @param req The Request with the virtual address of this request
         */
        void setTranslationRequest(const RequestPtr &req)
        {
            translationRequest = req;
        }

        void markDelayed() override
        {}

        void finish(const Fault &fault, const RequestPtr &req,
                            ThreadContext *tc, BaseMMU::Mode mode) override;

        /**
         * Issues the translation request to the provided MMU
         * @param mmu the mmu that has to translate the address
         */
        void startTranslation(BaseMMU *mmu);
    };

    std::list<DeferredPacket> pfq;
    std::list<DeferredPacket> pfqMissingTranslation;

    using const_iterator = std::list<DeferredPacket>::const_iterator;
    using iterator = std::list<DeferredPacket>::iterator;

    // PARAMETERS

    /** Maximum size of the prefetch queue */
    const unsigned queueSize;

    /**
     * Maximum size of the queue holding prefetch requests with missing
     * address translations
     */
    const unsigned missingTranslationQueueSize;

    /** Cycles after generation when a prefetch can first be issued */
    const Cycles latency;

    /** Squash queued prefetch if demand access observed */
    const bool queueSquash;

    /** Filter prefetches if already queued */
    const bool queueFilter;

    /** Snoop the cache before generating prefetch (cheating basically) */
    const bool cacheSnoop;

    /** Tag prefetch with PC of generating access? */
    const bool tagPrefetch;

    /** Percentage of requests that can be throttled */
    const unsigned int throttleControlPct;

    struct QueuedStats : public statistics::Group
    {
        QueuedStats(statistics::Group *parent);
        // STATS
        statistics::Scalar pfIdentified;
        statistics::Scalar pfBufferHit;
        statistics::Scalar pfInCache;
        statistics::Scalar pfRemovedDemand;
        statistics::Scalar pfRemovedFull;
        statistics::Scalar pfSpanPage;
        statistics::Scalar pfUsefulSpanPage;
    } statsQueued;
  public:
    using AddrPriority = std::pair<Addr, int32_t>;

    Queued(const QueuedPrefetcherParams &p);
    virtual ~Queued();

    void
    notify(const CacheAccessProbeArg &acc, const PrefetchInfo &pfi) override;

    void insert(const PacketPtr &pkt, PrefetchInfo &new_pfi, int32_t priority,
                const CacheAccessor &cache);

    virtual void calculatePrefetch(const PrefetchInfo &pfi,
                                   std::vector<AddrPriority> &addresses,
                                   const CacheAccessor &cache) = 0;
    PacketPtr getPacket() override;

    // [MDSPEC][R6-P-P04] P04-a injector-facing queue-valid fault.  Clears
    // the shadow valid bit of the first LIVE queue entry WITHOUT removing it
    // (the queue pointer/count are unchanged); getPacket skips it at issue.
    // On success writes the entry's address/PC and returns its 0-based
    // index; returns -1 when no live entry exists (ineligible).
    long chaosClearQueueValid(Addr &addr, Addr &pc);
    // [MDSPEC][R6-P-P04-a-F5-v2] Read the first live entry WITHOUT clearing
    // it.  The F5 latch selects this entry's fixed slot and performs the
    // single-bit invalidation itself; a pre-clear would change two bits.
    bool chaosPeekLiveQueueEntry(Addr &addr, Addr &pc) const;
    bool chaosHasLiveQueueEntry() const
    {
        for (const auto &d : pfq) {
            if (d.chaosQueueValid)
                return true;
        }
        return false;
    }
    // [MDSPEC][R6-P-P04-a-F5-v2] Permanent queue-valid fault, fixed-slot
    // model.  F5 is the run-long stuck tier: after the first eligible event
    // ONE physical valid bit reads 0 until the run ends (no recovery).  The
    // earlier mapping invalidated the whole ready queue plus every later
    // insertion, which changes N state bits and is a semantic expansion;
    // it is retained only as historical evidence.  This model latches the
    // slot of the first live entry and invalidates exactly that slot's
    // entry (at most one live entry per slot).  Later entries allocated to
    // the same logical slot are born invalid; every other slot is untouched
    // and issues normally.  Exactly ONE physical fault identity
    // (fault_id/pfid) is latched per run; each birth/skip is a propagation
    // instance of that same fault.
    size_t chaosLatchQueueValidStuck(
        uint64_t fault_id, uint64_t pfid,
        std::vector<std::pair<Addr, Addr>> &invalidated);
    bool chaosQueueValidStuckActive() const { return chaosQueueValidStuck; }
    uint64_t chaosStuckSlot() const { return chaosStuckSlotIdx; }
    // Read-only snapshot of the live ready-queue entries (addr, pc) so the
    // injector can register their lineage under the latched fault identity.
    size_t chaosCollectLiveEntries(
        std::vector<std::pair<Addr, Addr>> &out) const;
    // [MDSPEC][R6-P-P04] P04-c entry-selection fault: swap the second live
    // entry into the head position so getPacket issues the WRONG entry next.
    // The correct head remains in the queue (moved behind it) — this is a
    // selection error, not a drop/dup.  Returns the selected (wrong) head
    // index, or -1 when fewer than two live entries exist.
    // displaced_addr receives the entry that WOULD have been issued
    // (the original correct head); it stays queued and is issued later.
    long chaosSelectWrongEntry(Addr &addr, Addr &pc, Addr &displaced_addr);
    // Attach the fault identity to the two shadow-marked entries so the
    // issue-time observer can report both real issues on the chain.
    void chaosAnnotateSelection(uint64_t fault_id, uint64_t pfid);
    // Observation-only real-issue observer (P04-c).  role is
    // "wrong_selected" or "head_issued_late".  Null by default.
    using ChaosQueueIssueObserver = void (*)(const char *role, Addr addr,
                                             uint64_t fault_id,
                                             uint64_t pfid);
    static ChaosQueueIssueObserver chaosQueueIssueObserver;
    // [MDSPEC][R6-P-P04-b] Arm a one-shot tail-pointer -1 insertion: the
    // next addToQueue(pfq, ...) inserts BEFORE the current tail (tail-1),
    // preserving every entry (no drop/dup).  The fault identity is attached
    // to the inserted entry and the shifted former tail for issue-time
    // observation.
    void chaosArmTailPointerBack(uint64_t fault_id, uint64_t pfid)
    {
        chaosTailBack = true;
        chaosPendingFaultId = fault_id;
        chaosPendingPfid = pfid;
    }
    bool chaosTailPointerArmed() const { return chaosTailBack; }
    Addr chaosTailAddr() const
    {
        return pfq.empty() ? 0 : pfq.back().pfInfo.getAddr();
    }
    size_t chaosQueueSize() const { return pfq.size(); }
    bool chaosHasTwoLiveEntries() const
    {
        int n = 0;
        for (const auto &d : pfq) {
            if (d.chaosQueueValid && ++n >= 2)
                return true;
        }
        return false;
    }

    Tick nextPrefetchReadyTime() const override
    {
        return pfq.empty() ? MaxTick : pfq.front().tick;
    }

    void printQueue(const std::list<DeferredPacket> &queue) const;

  private:

    // [MDSPEC][R6-P-P04-b] One-shot tail-pointer -1 state.
    bool chaosTailBack = false;
    uint64_t chaosPendingFaultId = 0;
    uint64_t chaosPendingPfid = 0;

    // [MDSPEC][R6-P-P04-a-F5-v2] Latched run-long stuck-valid state (see
    // the public API above).  Default false => the issue/insertion paths
    // are byte-identical when no P04-F5 fault is mounted.
    bool chaosQueueValidStuck = false;
    uint64_t chaosStuckFaultId = 0;
    uint64_t chaosStuckPfid = 0;
    uint64_t chaosStuckSlotIdx = 0;
    uint64_t chaosEnqueueSeq = 0;
    // Mark a freshly inserted ready-queue entry invalid under the latched
    // physical fault and record the birth as a propagation instance.
    void chaosApplyStuckValid(DeferredPacket &dpp);

    /**
     * Adds a DeferredPacket to the specified queue
     * @param queue selected queue to use
     * @param dpp DeferredPacket to add
     */
    void addToQueue(std::list<DeferredPacket> &queue, DeferredPacket &dpp);

    /**
     * Starts the translations of the queued prefetches with a
     * missing translation. It performs a maximum specified number of
     * translations. Successful translations cause the prefetch request to be
     * queued in the queue of ready requests.
     * @param max maximum number of translations to perform
     */
    void processMissingTranslations(unsigned max);

    /**
     * Indicates that the translation of the address of the provided  deferred
     * packet has been successfully completed, and it can be enqueued as a
     * new prefetch request.
     * @param dp the deferred packet that has completed the translation request
     * @param failed whether the translation was successful
     * @param cache accessor for lookups on the cache that originated this pkt
     */
    void translationComplete(DeferredPacket *dp, bool failed,
                             const CacheAccessor &cache);

    /**
     * Checks whether the specified prefetch request is already in the
     * specified queue. If the request is found, its priority is updated.
     * @param queue selected queue to check
     * @param pfi information of the prefetch request to be added
     * @param priority priority of the prefetch request to be added
     * @return True if the prefetch request was found in the queue
     */
    bool alreadyInQueue(std::list<DeferredPacket> &queue,
                        const PrefetchInfo &pfi, int32_t priority);

    /**
     * Returns the maxmimum number of prefetch requests that are allowed
     * to be created from the number of prefetch candidates provided.
     * The behavior of this service is controlled with the throttleControlPct
     * parameter.
     * @param total number of prefetch candidates generated by the prefetcher
     * @return the number of these request candidates are allowed to be created
     */
    size_t getMaxPermittedPrefetches(size_t total) const;

    RequestPtr createPrefetchRequest(Addr addr, PrefetchInfo const &pfi,
                                        PacketPtr pkt);
};

} // namespace prefetch
} // namespace gem5

#endif //__MEM_CACHE_PREFETCH_QUEUED_HH__
